    [Xunit.Fact]
    public static void TestAlphaCandidatesNeedDictionaryOrAgreement() {
        emon.Testport.AssertEq(Ofuse.OfRule(1, 0, 0, 0, 0, 1, 0, 1000, 0), 5, "unflagged high confidence is insufficient");
